import{_ as t,o as r,c as o,a as i}from"./chunks/plugin-vue_export-helper.F1EaaLXR.js";const h=JSON.parse('{"title":"IDEF0 Editor — редактор функциональных диаграмм","description":"Кейс IDEF0 Editor: SVG и Vue 3, валидация ICOM по FIPS 183 на лету, декомпозиция по иерархии, IndexedDB и экспорт в SVG, PNG и JSON.","frontmatter":{"site":"pro","title":"IDEF0 Editor — редактор функциональных диаграмм","description":"Кейс IDEF0 Editor: SVG и Vue 3, валидация ICOM по FIPS 183 на лету, декомпозиция по иерархии, IndexedDB и экспорт в SVG, PNG и JSON.","head":[["link",{"rel":"canonical","href":"https://oleg-sidorkin.ru/work/idef0"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:title","content":"IDEF0 Editor — редактор функциональных диаграмм"}],["meta",{"property":"og:description","content":"Кейс IDEF0 Editor: SVG и Vue 3, валидация ICOM по FIPS 183 на лету, декомпозиция по иерархии, IndexedDB и экспорт в SVG, PNG и JSON."}],["meta",{"property":"og:url","content":"https://oleg-sidorkin.ru/work/idef0"}],["meta",{"property":"og:image","content":"https://oleg-sidorkin.ru/og.png"}],["meta",{"property":"og:site_name","content":"Oleg Sidorkin"}],["meta",{"property":"og:locale","content":"ru_RU"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"IDEF0 Editor — редактор функциональных диаграмм"}],["meta",{"name":"twitter:description","content":"Кейс IDEF0 Editor: SVG и Vue 3, валидация ICOM по FIPS 183 на лету, декомпозиция по иерархии, IndexedDB и экспорт в SVG, PNG и JSON."}],["meta",{"name":"twitter:image","content":"https://oleg-sidorkin.ru/og.png"}]]},"headers":[],"relativePath":"work/idef0.md","filePath":"work/idef0.md"}'),a={name:"work/idef0.md"};function n(l,e,d,s,p,c){return r(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="idef0-editor-—-редактор-функциональных-диаграмм" tabindex="-1">IDEF0 Editor — редактор функциональных диаграмм <a class="header-anchor" href="#idef0-editor-—-редактор-функциональных-диаграмм" aria-label="Permalink to &quot;IDEF0 Editor — редактор функциональных диаграмм&quot;">​</a></h1><p><strong>Задача.</strong> Описать бизнес-процесс по стандарту IDEF0 и показать схему коллегам. Специализированного браузерного редактора для этого стандарта не было: в универсальных рисовалках IDEF0 превращается в набор прямоугольников со стрелками.</p><p><strong>Ограничения.</strong> Внутренние процессы компании не хочется отправлять в чужое облако. Стандарт нишевой, поэтому редактор должен знать правила сам, а не полагаться на аккуратность автора.</p><h2 id="что-сделал" tabindex="-1">Что сделал <a class="header-anchor" href="#что-сделал" aria-label="Permalink to &quot;Что сделал&quot;">​</a></h2><ul><li>Движок на SVG и Vue 3: блоки, стрелки с манхэттенской маршрутизацией, ручное управление точками.</li><li><strong>Валидация ICOM по FIPS 183 на лету.</strong> Неправильно подключённая стрелка подсвечивается прямо на схеме, как ошибка компилятора.</li><li><strong>Декомпозиция</strong>: блок проваливается вглубь, иерархия процессов строится без потери контекста.</li><li>Данные в IndexedDB, открытые вкладки синхронизируются через localStorage.</li><li>Экспорт в SVG, PNG и JSON.</li></ul><p>Семантика стрелок строгая: вход слева, управление сверху, выход справа, механизм снизу. Именно это делает диаграмму проверяемой, а не картинкой.</p><h2 id="доказательство" tabindex="-1">Доказательство <a class="header-anchor" href="#доказательство" aria-label="Permalink to &quot;Доказательство&quot;">​</a></h2><ul><li>Живой редактор: <a href="/idef0.html">/idef0</a></li><li>Разбор архитектуры: <a href="/projects/idef0-editor.html">/projects/idef0-editor</a></li><li>Работает без сервера: данные не покидают браузер.</li></ul><h2 id="что-дальше" tabindex="-1">Что дальше <a class="header-anchor" href="#что-дальше" aria-label="Permalink to &quot;Что дальше&quot;">​</a></h2><ul><li>Импорт существующих диаграмм из JSON и обмен между проектами.</li><li>Печать в А4 с рамкой по стандарту.</li><li>Проверка полноты декомпозиции: подсказка, каких стрелок не хватает на дочерней диаграмме.</li></ul>',10)])])}const u=t(a,[["render",n]]);export{h as __pageData,u as default};
